public partial class MainForm {
 void EditSheet(){using(var f=FeatureForm("Samolepiace hárky",480,720)){var p=FeatureStack(f);var s=Read();var l=s.Layout;
  var enabled=Check(p,"Viac etikiet na hárku",l.Enabled);var width=Number(p,"Šírka papiera (mm)",(decimal)s.PageWidth,10,500,2);var height=Number(p,"Výška papiera (mm)",(decimal)s.PageHeight,10,500,2);
  var cols=Number(p,"Stĺpce",l.Columns,1,100,0);var rows=Number(p,"Riadky",l.Rows,1,100,0);var first=Number(p,"Prvá voľná pozícia (od 1)",l.FirstSlot+1,1,10000,0);var count=Number(p,"Počet etikiet",l.Count,1,10000,0);
  var left=Number(p,"Ľavý okraj (mm)",(decimal)l.Left,0,1000,2);var top=Number(p,"Horný okraj (mm)",(decimal)l.Top,0,1000,2);var right=Number(p,"Pravý okraj (mm)",(decimal)l.Right,0,1000,2);var bottom=Number(p,"Dolný okraj (mm)",(decimal)l.Bottom,0,1000,2);var gx=Number(p,"Vodorovná medzera (mm)",(decimal)l.HorizontalGap,0,1000,2);var gy=Number(p,"Zvislá medzera (mm)",(decimal)l.VerticalGap,0,1000,2);
  AddAccept(f,p,delegate{l.Enabled=enabled.Checked;l.Columns=(int)cols.Value;l.Rows=(int)rows.Value;l.FirstSlot=(int)first.Value-1;l.Count=(int)count.Value;l.Left=(double)left.Value;l.Top=(double)top.Value;l.Right=(double)right.Value;l.Bottom=(double)bottom.Value;l.HorizontalGap=(double)gx.Value;l.VerticalGap=(double)gy.Value;s.PageWidth=(double)width.Value;s.PageHeight=(double)height.Value;s.UsePaper=true;s.PaperPreset="Custom";OutputPlan.ValidateLayout(s);ChangeDocument(d=>{d.Layout=l;d.PageWidth=s.PageWidth;d.PageHeight=s.PageHeight;d.UsePaper=true;d.PaperPreset=s.PaperPreset;});});f.ShowDialog(this);
 }}
 void EditVariables(){using(var f=FeatureForm("Premenné polia",1050,520)){var table=new DataGridView{Dock=DockStyle.Fill,AutoGenerateColumns=false,AllowUserToAddRows=true,AllowUserToDeleteRows=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.AllCells};
  string[] names={"Názov","Typ (Number/Date/Fixed)","Začiatok","Krok","Číslice","Prefix","Suffix","Formát dátumu","Posun dní","Posun mesiacov","Pevný dátum","Dátum","Pevná hodnota"};for(int i=0;i<names.Length;i++){if(i==1){var types=new List<VariableTypeChoice>{new VariableTypeChoice{Key="Number",Name=Loc.T("Číslovanie")},new VariableTypeChoice{Key="Date",Name=Loc.T("Dátum")},new VariableTypeChoice{Key="Fixed",Name=Loc.T("Pevný text")}};table.Columns.Add(new DataGridViewComboBoxColumn{HeaderText=Loc.T("Typ"),DataSource=types,DisplayMember="Name",ValueMember="Key"});}else if(i==10)table.Columns.Add(new DataGridViewCheckBoxColumn{HeaderText=Loc.T(names[i])});else table.Columns.Add(names[i],Loc.T(names[i]));}table.DefaultValuesNeeded+=delegate(object sender,DataGridViewRowEventArgs e){object[] defaults={"serial","Number",1,1,6,"","","yyyy-MM-dd",0,0,false,DateTime.Today.ToString("yyyy-MM-dd"),""};for(int i=0;i<defaults.Length;i++)e.Row.Cells[i].Value=defaults[i];};
  foreach(var v in variables)table.Rows.Add(v.Name,v.Type,v.Start,v.Step,v.Digits,v.Prefix,v.Suffix,v.Format,v.Days,v.Months,v.FixedDate,v.Date.ToString("yyyy-MM-dd"),v.FixedValue);
  f.Controls.Add(table);var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,AutoSize=true};footer.Controls.Add(new Label{Text=Loc.T("Použitie v texte alebo kóde: {serial}. Typ: Number, Date alebo Fixed."),AutoSize=true});footer.Controls.Add(Btn(Loc.T("Použiť"),delegate{try{table.EndEdit();var list=new List<VariableField>();foreach(DataGridViewRow r in table.Rows){if(r.IsNewRow)continue;Func<int,string,string> get=(i,fallback)=>string.IsNullOrEmpty(Convert.ToString(r.Cells[i].Value))?fallback:Convert.ToString(r.Cells[i].Value);list.Add(new VariableField{Name=get(0,"serial"),Type=get(1,"Number"),Start=long.Parse(get(2,"1")),Step=long.Parse(get(3,"1")),Digits=int.Parse(get(4,"6")),Prefix=get(5,""),Suffix=get(6,""),Format=get(7,"yyyy-MM-dd"),Days=int.Parse(get(8,"0")),Months=int.Parse(get(9,"0")),FixedDate=bool.Parse(get(10,"false")),Date=DateTime.ParseExact(get(11,DateTime.Today.ToString("yyyy-MM-dd")),"yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture),FixedValue=get(12,"")});}var test=Read();test.Variables=list;BatchData.Variables(test,0,DateTime.Now);ChangeDocument(s=>s.Variables=list);f.Close();}catch(Exception ex){Error(ex);}}));f.Controls.Add(footer);ApplyColors(f);f.ShowDialog(this);}}
 void ExportJob(OutputPlan plan,double dpiValue,string preferred=null,IWin32Window parent=null,Action<LabelIssue> navigate=null){
  var owner=parent??this;PreflightReport report;
  if(!RunWork(owner,"validate-output","Kontrolujem výstup…",()=>PreflightReport.Inspect(plan),out report))return;
  if(!ReviewExport(owner,report,preferred==null?Loc.T("Vybrané záznamy"):preferred.ToUpperInvariant(),navigate??NavigateOutputIssue))return;
  using(var dialog=new SaveFileDialog{Filter="PDF|*.pdf|Word|*.docx|"+(plan.PageCount>1?"SVG (ZIP)|*.zip":"SVG|*.svg")+"|ZPL|*.zpl",FilterIndex=Math.Max(1,Array.IndexOf(new[]{"pdf","docx","svg","zpl"},preferred)+1),FileName="ND-LabelDesigner"})if(showExportSave(dialog,owner)==DialogResult.OK){
   string format=new[]{"pdf","docx","svg","zpl"}[dialog.FilterIndex-1],path=dialog.FileName;bool done;
   if(RunWork(owner,"export-"+format,"Exportujem…",delegate{AtomicOutput.Save(path,p=>JobOutput.Export(p,format,plan,dpiValue));return true;},out done))status.Text=Loc.T("Export uložený: ")+path;
  }
 }
 void ShowBatch(){using(var window=new BatchWindow(this))window.Show();}
}
